async function saveSurveys(items, concurrency = 4) {
  const results = [];
  for (let i = 0; i < items.length; i += concurrency) {
    const batch = items.slice(i, i + concurrency);
    const batchRes = await Promise.all(batch.map(item => fetch('/api/surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(item)
    }).then(r => r.json())));
    results.push(...batchRes);
  }
  return results;
}
