async function fetchProjectWithRetry(id, retries = 2) {
  for (let i = 0; i <= retries; i++) {
    try {
      const res = await fetch(`/api/projects/${id}`);
      if (!res.ok) throw new Error(res.status);
      return await res.json();
    } catch (err) {
      if (i === retries) throw err;
      await new Promise(r => setTimeout(r, 300 * (i + 1)));
    }
  }
}
async function loadAllProjects(ids) {
  return Promise.allSettled(ids.map(id => fetchProjectWithRetry(id))).then(results => results.filter(r => r.status === 'fulfilled').map(r => r.value));
}
