  const decoder = new TextDecoder();
  let buffer = '';
  while (true) {
    const {
      done,
      value
    } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, {
      stream: true
    });
    const lines = buffer.split('\n');
    buffer = lines.pop();
