async function processInvoiceBatch(ids, concurrency = 4) {
  const process = async id => {
    const raw = await fetch(`/api/invoices/${id}`).then(r => r.json());
    const transformed = transform(raw);
    return fetch(`/api/invoices/${id}`, {
      method: 'PUT',
      body: JSON.stringify(transformed)
    }).then(r => r.json());
  };
  const results = [];
  for (let i = 0; i < ids.length; i += concurrency) {
    const batch = await Promise.all(ids.slice(i, i + concurrency).map(process));
    results.push(...batch);
  }
  return results;
}
